BEGIN TRANSACTION;
CREATE TABLE clanovi (
    id TEXT PRIMARY KEY,
    ime TEXT NOT NULL,
    prezime TEXT DEFAULT 'Zehić',
    spol TEXT NOT NULL, -- 'M' ili 'Ž'
    generacija INTEGER NOT NULL,
    grana TEXT NOT NULL,
    datumi TEXT,
    napomene TEXT,
    roditelj_id TEXT,
    ime_roditelja TEXT,
    supruznik_ime TEXT,
    supruznik_napomene TEXT,
    je_supruznik INTEGER DEFAULT 0
);
CREATE INDEX idx_ime ON clanovi(ime);
CREATE INDEX idx_grana ON clanovi(grana);
CREATE INDEX idx_generacija ON clanovi(generacija);
CREATE INDEX idx_spol ON clanovi(spol);
COMMIT;
